def main():
	ones = s.count('1')
	zeroes = s.count('0')
	rand = s.count('?')
	diff = abs(ones - zeroes)
	added_ones = 0
	added_zeroes = 0
	if ones < zeroes:
		added_ones = diff
		rand -= diff
	else:
		added_zeroes = diff
		rand -= diff
	if rand > 0:
		added_zeroes += rand // 2
		added_ones += rand - rand // 2
	ans = ''
	for ele in s:
		if ele == '?':
			if added_ones > 0:
				ans = ans + '1'
				added_ones -= 1
			else:
				ans = ans + '0'
		else:
			ans = ans + ele
	print(ans)
t = int(input())
for _ in range(t):
